import{_ as e,o as d,c as a,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/WEIGHT.md","filePath":"manual-en/WEIGHT.md","lastUpdated":1785684581000}'),i={name:"manual-en/WEIGHT.md"};function r(n,t,o,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h3 id="_13-7-weight" tabindex="-1">13.7 WEIGHT <a class="header-anchor" href="#_13-7-weight" aria-label="Permalink to &quot;13.7 WEIGHT&quot;">​</a></h3><pre><code>WEIGHT BY var_name.
WEIGHT OFF.
</code></pre><p><code>WEIGHT</code> assigns cases varying weights, changing the frequency distribution of the active dataset. Execution of <code>WEIGHT</code> is delayed until data have been read.</p><p>If a variable name is specified, <code>WEIGHT</code> causes the values of that variable to be used as weighting factors for subsequent statistical procedures. Use of keyword <code>BY</code> is optional but recommended. Weighting variables must be numeric. Scratch variables may not be used for weighting (see <a href="./Scratch-Variables">Scratch Variables</a>).</p><p>When <code>OFF</code> is specified, subsequent statistical procedures weight all cases equally.</p><p>A positive integer weighting factor w on a case yields the same statistical output as would replicating the case w times. A weighting factor of 0 is treated for statistical purposes as if the case did not exist in the input. Weighting values need not be integers, but negative and system-missing values for the weighting variable are interpreted as weighting factors of 0. User-missing values are not treated specially.</p><p>When <code>WEIGHT</code> is specified after <code>TEMPORARY</code>, it affects only the next procedure (see <a href="./TEMPORARY">TEMPORARY</a>).</p><p><code>WEIGHT</code> does not cause cases in the active dataset to be replicated in memory.</p><h4 id="_13-7-1-example-weights" tabindex="-1">13.7.1 Example Weights <a class="header-anchor" href="#_13-7-1-example-weights" aria-label="Permalink to &quot;13.7.1 Example Weights&quot;">​</a></h4><p>One could define a dataset containing an inventory of stock items. It would be reasonable to use a string variable for a description of the item, and a numeric variable for the number in stock, like in Example 13.5.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data list notable list /item (a16) quantity (f8.0). begin   data nuts    345 screws  10034 washers 32012 bolts   876 end data.  echo &#39;Unweighted frequency table&#39;. frequencies /variables = item /format=dfreq.  weight by quantity.  echo &#39;Weighted frequency table&#39;. frequencies /variables = item /format=dfreq.</span></span></code></pre></div><p><strong>Example 13.5:</strong> Setting the weight on the variable <strong>quantity</strong></p><p>One analysis which most surely would be of interest is the relative amounts or each item in stock. However without setting a weight variable, <code>FREQUENCIES</code> (see <a href="./FREQUENCIES">FREQUENCIES</a>) does not tell us what we want to know, since there is only one case for each stock item. Example 13.6 shows the difference between the weighted and unweighted frequency tables.</p><table tabindex="0"><thead><tr><th></th><th></th><th>Frequency</th><th>Percent</th><th>Valid Percent</th><th>Cumulative Percent</th></tr></thead><tbody><tr><td>Valid</td><td>bolts</td><td>1</td><td>25.0%</td><td>25.0%</td><td>25.0%</td></tr><tr><td>nuts</td><td>1</td><td>25.0%</td><td>25.0%</td><td>50.0%</td><td></td></tr><tr><td>screws</td><td>1</td><td>25.0%</td><td>25.0%</td><td>75.0%</td><td></td></tr><tr><td>washers</td><td>1</td><td>25.0%</td><td>25.0%</td><td>100.0%</td><td></td></tr><tr><td>Total</td><td>4</td><td>100.0%</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Frequency</td><td>Percent</td><td>Valid Percent</td><td>Cumulative Percent</td></tr><tr><td>Valid</td><td>washers</td><td>32012</td><td>74.0%</td><td>74.0%</td><td>74.0%</td></tr><tr><td>screws</td><td>10034</td><td>23.2%</td><td>23.2%</td><td>97.2%</td><td></td></tr><tr><td>bolts</td><td>876</td><td>2.0%</td><td>2.0%</td><td>99.2%</td><td></td></tr><tr><td>nuts</td><td>345</td><td>.8%</td><td>.8%</td><td>100.0%</td><td></td></tr><tr><td>Total</td><td>43267</td><td>100.0%</td><td></td><td></td><td></td></tr></tbody></table><p><strong>Example 13.6:</strong> Weighted and unweighted frequency tables of <strong>items</strong></p>`,15)])])}const g=e(i,[["render",r]]);export{p as __pageData,g as default};
